<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import PotreeFrame from '@/components/PotreeFrame.vue'
import { applyDesensitization, createDesensitizationRule, deleteDesensitizationRule, getDesensitizationRules, mapDesensitizationRule, updateDesensitizationRule } from '@/api/desensitization'
import { getCaseVersion } from '@/api/cases'
import { getViewerConfig } from '@/api/viewer'
import type { BoxRange, DerivedVersionResult, DesensitizationRule, DesensitizationRulePayload, DesensitizationRuleType } from '@/types/desensitization'

const route = useRoute(); const router = useRouter(); const caseId = String(route.params.caseId); const versionId = String(route.params.versionId); const mock = import.meta.env.VITE_USE_MOCK !== 'false'
const frame = ref<InstanceType<typeof PotreeFrame>>(); const loading = ref(true); const saving = ref(false); const error = ref(''); const lockedReason = ref(''); const manifestUrl = ref(''); const rules = ref<DesensitizationRule[]>([]); const forcedRules = ref<DesensitizationRule[]>([]); const previewHide = ref(false); const editing = ref<DesensitizationRule>(); const derived = ref<DerivedVersionResult>(); const poller = ref<number>(); const sourceStatus = ref('')
const form = ref<DesensitizationRulePayload>({ type: 'HIDE', title: '', description: '', range: { min: [0, 0, 0], max: [1, 1, 1] } })
const readOnly = computed(() => Boolean(lockedReason.value) || ['PUBLISHED', 'ARCHIVED'].includes(sourceStatus.value) || rules.value.some((rule) => rule.status === 'APPLIED'))
const masks = computed(() => [...forcedRules.value, ...rules.value].map((rule) => ({ id: rule.id, type: rule.type, title: rule.title, range: rule.range, enforced: rule.enforced })))
const ranges = ['X 最小', 'Y 最小', 'Z 最小', 'X 最大', 'Y 最大', 'Z 最大']
function message(error: unknown, fallback: string) { return error instanceof Error ? error.message : fallback }
function validRange(range: BoxRange) { return range.min.every((item, index) => Number.isFinite(item) && item < range.max[index]) }
function resetForm() { editing.value = undefined; form.value = { type: 'HIDE', title: '', description: '', range: { min: [0, 0, 0], max: [1, 1, 1] } } }
function edit(rule: DesensitizationRule) { editing.value = rule; form.value = { type: rule.type, title: rule.title, description: rule.description, range: { min: [...rule.range.min] as [number, number, number], max: [...rule.range.max] as [number, number, number] } }; window.scrollTo({ top: 0, behavior: 'smooth' }) }
async function load() { loading.value = true; error.value = ''; try { const [config, current, version] = await Promise.all([getViewerConfig(versionId), getDesensitizationRules(versionId), getCaseVersion(versionId)]); sourceStatus.value = version.status; manifestUrl.value = config.manifestUrl; rules.value = current; forcedRules.value = config.forcedDesensitizationRules.map((item) => ({ ...mapDesensitizationRule({ ...item, enforced: true }), enforced: true })); if (!mock && !manifestUrl.value) error.value = '后端未返回受控 Viewer 清单，无法加载点云。' } catch (cause) { error.value = message(cause, '脱敏工作台加载失败') } finally { loading.value = false } }
async function save() { if (readOnly.value) return; if (!form.value.title.trim()) { ElMessage.warning('请输入规则标题'); return } if (!validRange(form.value.range)) { ElMessage.warning('范围坐标必须满足每个轴的最小值小于最大值'); return } saving.value = true; try { if (editing.value) await updateDesensitizationRule(editing.value.id, { ...form.value, title: form.value.title.trim() }); else await createDesensitizationRule(versionId, { ...form.value, title: form.value.title.trim() }); await load(); resetForm(); ElMessage.success('脱敏规则已保存') } catch (cause) { if ((cause as { response?: { status?: number; data?: { message?: string } } }).response?.status === 409) lockedReason.value = (cause as { response?: { data?: { message?: string } } }).response?.data?.message || '后端已锁定该版本，不能再编辑脱敏规则。'; ElMessage.error(lockedReason.value || message(cause, '规则保存失败')) } finally { saving.value = false } }
async function remove(rule: DesensitizationRule) { if (rule.enforced || rule.status !== 'DRAFT') { ElMessage.warning('强制规则或已应用规则不能删除'); return } try { await ElMessageBox.confirm(`确认删除规则“${rule.title}”？`, '删除未应用规则', { type: 'warning' }); await deleteDesensitizationRule(rule.id); await load(); ElMessage.success('规则已删除') } catch (cause) { if (cause !== 'cancel') ElMessage.error(message(cause, '规则删除失败')) } }
async function apply() { if (readOnly.value) return; const deleting = rules.value.some((rule) => rule.type === 'DELETE'); try { await ElMessageBox.confirm(deleting ? 'DELETE 将生成派生版本，不会覆盖原始版本；请确认规则范围已人工复核。' : '将按当前规则创建脱敏派生版本，不会覆盖原始版本。', '执行脱敏', { type: 'warning', confirmButtonText: '确认执行' }); saving.value = true; const result = await applyDesensitization(versionId); derived.value = result; ElMessage.success(mock ? '模拟模式仅记录处理中状态，未执行 PDAL。' : '脱敏任务已提交'); if (result.versionId && result.status === 'PROCESSING') startPolling(result.versionId) } catch (cause) { if (cause !== 'cancel') ElMessage.error(message(cause, '脱敏执行失败')) } finally { saving.value = false } }
function startPolling(id: string) { window.clearInterval(poller.value); poller.value = window.setInterval(async () => { try { const current = await getCaseVersion(id); if (derived.value) Object.assign(derived.value, { versionId: current.id, status: current.status, jobId: current.jobId, progress: current.progress, failureReason: current.failureReason }); if (current.status !== 'PROCESSING') window.clearInterval(poller.value) } catch { /* 后端尚未提供派生版本详情时保持最后状态。 */ } }, 4000) }
function gotoDerived() { router.push({ path: `/admin/cases/${caseId}`, query: { versionId: derived.value?.versionId || undefined } }) }
onMounted(load); onBeforeUnmount(() => window.clearInterval(poller.value))
</script>

<template>
  <main class="workspace"><header><div><p>管理员 / 案例脱敏</p><h1>脱敏规则工作台</h1></div><div><el-tag v-if="mock" type="warning">模拟脱敏模式</el-tag><el-button @click="router.push(`/admin/cases/${caseId}`)">返回案例</el-button></div></header>
    <el-alert v-if="mock" title="模拟脱敏模式" description="不会伪造 PDAL 成功或真实点云处理；“执行脱敏”仅演示派生版本处理中状态。" type="warning" :closable="false" show-icon />
    <el-alert v-if="readOnly" title="当前版本只读" description="已发布、已归档或已应用规则的版本不能再编辑脱敏规则。" type="info" :closable="false" show-icon />
    <el-alert v-if="error" title="无法加载脱敏工作台" :description="error" type="error" :closable="false" show-icon />
    <el-skeleton v-else-if="loading" :rows="12" animated />
    <section v-else class="layout"><div class="viewer"><PotreeFrame ref="frame" :manifest-url="manifestUrl" :mock="mock" :masks="masks" :hide-preview="previewHide" @error="error=$event" /><p class="legend"><span class="hide">HIDE</span> 遮挡预览，不代表物理删除　<span class="delete">DELETE</span> 将由后端生成派生版本</p></div><aside>
      <el-switch v-model="previewHide" active-text="预览 HIDE 遮挡" :disabled="!masks.some(item=>item.type==='HIDE')" />
      <el-divider>规则编辑</el-divider><el-form label-position="top"><el-form-item label="处理方式"><el-radio-group v-model="form.type" :disabled="readOnly"><el-radio value="HIDE">HIDE（遮挡）</el-radio><el-radio value="DELETE">DELETE（派生删除）</el-radio></el-radio-group></el-form-item><el-form-item label="标题"><el-input v-model="form.title" :disabled="readOnly" /></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :disabled="readOnly" /></el-form-item><el-form-item label="三维 BOX 范围"><div class="coordinates"><el-input-number v-model="form.range.min[0]" :precision="3" :disabled="readOnly" placeholder="X 最小" /><el-input-number v-model="form.range.max[0]" :precision="3" :disabled="readOnly" placeholder="X 最大" /><el-input-number v-model="form.range.min[1]" :precision="3" :disabled="readOnly" placeholder="Y 最小" /><el-input-number v-model="form.range.max[1]" :precision="3" :disabled="readOnly" placeholder="Y 最大" /><el-input-number v-model="form.range.min[2]" :precision="3" :disabled="readOnly" placeholder="Z 最小" /><el-input-number v-model="form.range.max[2]" :precision="3" :disabled="readOnly" placeholder="Z 最大" /></div></el-form-item><el-button type="primary" :loading="saving" :disabled="readOnly" @click="save">{{editing?'保存修改':'新增规则'}}</el-button><el-button v-if="editing" @click="resetForm">取消编辑</el-button></el-form>
      <el-divider>脱敏规则</el-divider><el-empty v-if="!rules.length&&!forcedRules.length" description="暂无脱敏规则" /><div v-for="rule in [...forcedRules,...rules]" :key="rule.id" class="rule"><el-tag :type="rule.type==='DELETE'?'danger':'warning'">{{rule.type}}</el-tag><b>{{rule.title}}</b><el-tag v-if="rule.enforced" size="small" type="info">强制遮挡</el-tag><p>{{rule.description||'无说明'}}</p><small>min [{{rule.range.min.join(', ')}}]　max [{{rule.range.max.join(', ')}}]　{{rule.status}}</small><div><el-button link :disabled="readOnly||rule.enforced" @click="edit(rule)">编辑</el-button><el-button link type="danger" :disabled="readOnly||rule.enforced||rule.status!=='DRAFT'" @click="remove(rule)">删除</el-button></div></div>
      <el-divider>执行脱敏</el-divider><el-button type="danger" :loading="saving" :disabled="readOnly||!rules.length" @click="apply">生成脱敏派生版本</el-button><div v-if="derived" class="derived"><b>派生版本状态：</b><el-tag :type="derived.status==='FAILED'?'danger':derived.status==='READY'?'success':'warning'">{{derived.status}}</el-tag><el-progress v-if="derived.status==='PROCESSING'&&derived.progress!==null" :percentage="derived.progress" /><p v-if="derived.failureReason" class="failure">{{derived.failureReason}}</p><el-button v-if="derived.versionId&&derived.status==='READY'" link type="primary" @click="gotoDerived">查看派生版本详情</el-button></div>
    </aside></section>
  </main>
</template>
<style scoped>.workspace{min-height:100vh;background:#f4f7fb}.workspace>header{height:76px;padding:14px 24px;display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid #dde4ee}.workspace>header p{margin:0;color:#64748b;font-size:12px}h1{margin:5px 0;font-size:20px}.workspace>:deep(.el-alert){margin:16px 24px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 390px;height:calc(100vh - 108px)}.viewer{position:relative;min-width:0}.legend{position:absolute;bottom:5px;left:12px;padding:6px 8px;background:#ffffffdb;font-size:12px}.hide,.delete{padding:2px 4px;color:#fff;border-radius:3px}.hide{background:#e6a23c}.delete{background:#d14343}aside{overflow:auto;padding:16px;background:#fff;border-left:1px solid #dde4ee}.coordinates{display:grid;grid-template-columns:1fr 1fr;gap:8px;width:100%}.rule{padding:10px 0;border-bottom:1px solid #edf1f6}.rule b,.rule .el-tag{margin-right:7px}.rule p{margin:7px 0;font-size:13px}.rule small{color:#64748b;font-size:11px;word-break:break-all}.derived{margin-top:14px;padding:10px;background:#fff7e6}.failure{color:#c45656}@media(max-width:1100px){.layout{grid-template-columns:1fr;height:auto}.viewer{height:56vh}aside{border-left:0;border-top:1px solid #dde4ee}}</style>
